  var g19 = S19.generals[0];
  g19.cityId = city19.id; g19.status = 'mayor';
  var mb19 = G.mayorBonus(city19);
  check('任命城主后取到加成', !!mb19.name, mb19.name);
  check('城主·治理 → 产量加成', mb19.prod > 0, '+' + (mb19.prod * 100).toFixed(1) + '%');
  check('城主·谋略 → 研究加速', mb19.research > 0, '+' + (mb19.research * 100).toFixed(1) + '%');
  check('城主·谋略 → 城防加成', mb19.def > 0, '+' + (mb19.def * 100).toFixed(1) + '%');
  check('城主**不**给征兵加速（那是守将的武职）', !G.guardBonus(city19).train);
  var grainYes = G.productionPerSec().grain;
  check('城主在任 → 净水产量实际提升', grainYes > grainNo,
    (grainNo * 3600).toFixed(1) + ' → ' + (grainYes * 3600).toFixed(1) + '/时');
  var g19g = S19.generals[1];
  g19g.cityId = city19.id; g19g.status = 'guard';
  check('守将·武力 → 征兵加速', G.guardBonus(city19).train > 0,
    '+' + (G.guardBonus(city19).train * 100).toFixed(1) + '%');
  check('守将**不**给产量加成（已迁城主，防两个出口）',
    !G.prodFactors('grain', city19).some(function (f) { return f.name === '守将治理'; }));
  check('prodFactors 的产量项名为「城主治理」',
    G.prodFactors('grain', city19).some(function (f) { return f.name === '城主治理'; }));

  /* ---- v53（老板）：**一城一守将** ----
     改前可以给同一座城连任多个守将，而 guardGeneralOf 只取第一个匹配 →
     后任的将静默失效、加成仍挂在旧将身上（老板看到的就是"任命了新守将，
     加成链条数值没跟着新英雄的属性走"）。 */
  console.log('  --- 一城一守将（v53 老板） ---');
  (function () {
    var st = G.state;
    var cityA = st.cities[0];
    var gA = st.generals[0], gB = st.generals[1];
    /* 造两个属性差异明显的将，验证"加成链随新将重算" */
    gA.status = 'idle'; gA.cityId = null; gA.equip = {};
    gB.status = 'idle'; gB.cityId = null; gB.equip = {};
    gA.nz = 20; gB.nz = 90;
    /* v89.113：治理加成归城主 —— 本段改测**城主任命链**（守将的链由武力项另测） */
    var r1 = G.assignGeneral(gA.id, 'mayor', cityA.id);
    var prodA = G.mayorBonus(cityA).prod;
    var r2 = G.assignGeneral(gB.id, 'mayor', cityA.id);
    var prodB = G.mayorBonus(cityA).prod;
    check('任命第二人 → 第一人自动解任（不留双任）',
      gA.status === 'idle' && gA.cityId === null && gB.status === 'mayor' && gB.cityId === cityA.id,
      'A=' + gA.status + ' B=' + gB.status);
    check('加成链改由**新城主**的属性计算（治理 20 → 90）',
      G.mayorGeneralOf(cityA) === gB && prodB > prodA && Math.abs(prodB - 0.9) < 1e-9,
      (prodA * 100).toFixed(1) + '% → ' + (prodB * 100).toFixed(1) + '%');
    /* v89.113：守将侧同款链（武力 20 → 90 → 征兵 +10% → +45%） */
    gA.status = 'idle'; gB.status = 'idle';
    gA.yw = 20; gB.yw = 90;
    G.assignGeneral(gA.id, 'guard', cityA.id);
    var trA = G.guardBonus(cityA).train;
    G.assignGeneral(gB.id, 'guard', cityA.id);
    var trB = G.guardBonus(cityA).train;
    check('守将链随新将重算（武力 20 → 90 → 征兵 10% → 45%）',
      G.guardGeneralOf(cityA) === gB && Math.abs(trB - 0.45) < 1e-9 && trB > trA,
      (trA * 100).toFixed(1) + '% → ' + (trB * 100).toFixed(1) + '%');
    /* 一人一职互斥：把 gB 从守将改成城主 → 守将位自动空出（status 单值） */
    G.assignGeneral(gB.id, 'mayor', cityA.id);
    check('一人一职（守将改任城主 → 守将位不再挂在该将名下）',
      gB.status === 'mayor' && !G.guardGeneralOf(cityA));
    check('提示文案点明"已自动解除"（玩家得知道旧任没了）',
      r2.ok && /已自动解除/.test(r2.msg) && r2.msg.indexOf(gA.name) >= 0, r2.msg);
    check('同一座城不可能挂两个守将（不变量，按全境逐城核）', (function () {
      var seen = {}, dup = 0;
      st.generals.forEach(function (g) {
        if (g.status !== 'guard' || !g.cityId) return;
        if (seen[g.cityId]) dup++; else seen[g.cityId] = 1;
      });
      return dup === 0;
    })());
    /* 一个人不能同时守两座城：换城时应把旧城的守将身份一并带走 */
    var cityB2 = G.makeCity({ id: 'v53_city2', name: 'v53二城', x: 301, y: 301 });
    st.cities.push(cityB2);
    G.assignGeneral(gB.id, 'guard', cityB2.id);
    check('守将换城 → 旧城不再留人（不会一个将守两座城）',
      G.guardGeneralOf(cityB2) === gB && G.guardGeneralOf(cityA) === null && gB.cityId === cityB2.id);
    /* 读档归一化：旧档同城多守将 → 只留最先的那位 */
    gA.status = 'guard'; gA.cityId = cityA.id;
    gB.status = 'guard'; gB.cityId = cityA.id;
    var released = G.normalizeGuards();
    check('读档归一化只留首位（旧档遗留的双任被清掉）',
      released.length === 1 && G.guardGeneralOf(cityA) !== null
      && st.generals.filter(function (g) { return g.status === 'guard' && g.cityId === cityA.id; }).length === 1,
      '清掉 ' + released.join('、'));
    /* 老存档里已经挂了双任的，读进来也必须被清掉 —— 否则老板读档后
       "新守将不生效"依旧存在（迁移没接线 = 只对新档生效） */
    /* v67：后处理整段搬进了 GAME.adoptState（主档读档与槽位读档**共用同一个出口**）。
       判据跟着改成"两段合起来看"：loadGame 必须**转交** adoptState，
       且 adoptState 段里确实调了两个归一化 —— 只断言前半段会退化成装饰。 */
    check('读档路径真的调了归一化（旧档不靠玩家重新任命）', (function () {
      var stSrc = stripComment(require('fs').readFileSync(require('path').join(__dirname, 'js', 'state.js'), 'utf8'));
      var i = stSrc.indexOf('GAME.loadGame = function');
      var segL = i < 0 ? '' : stSrc.slice(i, stSrc.indexOf('\n  };', i));
      var j = stSrc.indexOf('GAME.adoptState = function');
      var segA = j < 0 ? '' : stSrc.slice(j, stSrc.indexOf('\n  };', j));
      return segL.length > 100 && /GAME\.adoptState\(st\)/.test(segL)
        && segA.length > 3000
        && /GAME\.normalizeGuards\(\)/.test(segA)
        && /GAME\.normalizeGenCities\(\)/.test(segA);
    })(), 'loadGame 转交 adoptState；后处理段 ' + (function () {
      var t = stripComment(require('fs').readFileSync(require('path').join(__dirname, 'js', 'state.js'), 'utf8'));
      var j = t.indexOf('GAME.adoptState = function');
      return j < 0 ? 0 : (t.indexOf('\n  };', j) - j);
    })() + ' 字符');
    /* 复原，免得影响后面的断言 */
    st.cities.pop();
    st.generals.forEach(function (g) { g.status = 'idle'; g.cityId = null; });
    g19.cityId = city19.id; g19.status = 'guard';
  })();

  console.log('  --- 装备对英雄/战斗的加成 ---');
  var gEq = S19.generals[1] || S19.generals[0];
  gEq.equip = {};
  var base19 = G.genAttrs(gEq);
  gEq.equip.weapon = 'rare_zhan_weapon';   // 陨锋长剑：atk 2888
  var withW = G.genAttrs(gEq);
  check('武器装备 → 英雄攻击属性上升', withW.atk > base19.atk,
    base19.atk + ' → ' + withW.atk);
  /* v91.91：防御刻度下调后 4000 打 6000 会被全歼（两边 atkLoss 都 = 4000，比不出差），
     抬到 8000 才留得住"损兵差"这个被测变量。 */
  var army19 = { buxingji: 8000 }, foe19 = { buxingji: 6000 };
  var rA = G.battle.simulate(army19, gEq, foe19, 0, null);
  gEq.equip.weapon = undefined;
  var rB = G.battle.simulate(army19, gEq, foe19, 0, null);
  check('装备武器 → 我军损失大幅减少（装备攻击已并入战斗）', rA.atkLoss < rB.atkLoss,
    '无武器损兵 ' + rB.atkLoss + ' → 有武器损兵 ' + rA.atkLoss);
  /* 英雄体力（装备 hp）→ 全军生命加成（此前该属性被算出却从未参与战斗） */
  gEq.equip = { head: 'prime_ti_head', chest: 'prime_ti_chest', ring: 'rare_zhi_ring' };   // 玄铁散件：合计 hp 2100
  var hpMult = 1 + Math.min(1.0, G.genAttrs(gEq).hp / 10000);
  var rHp = G.battle.simulate(army19, gEq, foe19, 0, null);
  gEq.equip = {};
  var rNoHp = G.battle.simulate(army19, gEq, foe19, 0, null);
  check('英雄体力 → 全军生命加成生效（损兵更少）', rHp.atkLoss < rNoHp.atkLoss,
    '无体力损兵 ' + rNoHp.atkLoss + ' → 有体力(hp=' + G.genAttrs({ equip: {}, hp: 100 }).hp + '/' + (1 + 0.21).toFixed(2) + 'x)损兵 ' + rHp.atkLoss);
  delete gEq.equip.weapon;
  gEq.equip.mount = 'coarse_zhi_mount';
  var withM = G.genAttrs(gEq);
  check('座驾（绝影）→ 英雄速度上升', withM.spd > base19.spd, base19.spd + ' → ' + withM.spd);
  delete gEq.equip.mount;
  var armorItem = null;
  for (var ek in DATA.EQUIP) { if (DATA.EQUIP[ek].def) { armorItem = ek; break; } }
  if (armorItem) {
    gEq.equip.chest = armorItem;
    check('护甲 → 英雄防御属性上升', G.genAttrs(gEq).def > base19.def,
      base19.def + ' → ' + G.genAttrs(gEq).def);
    delete gEq.equip.chest;
  } else {
    check('护甲类装备存在', true, '数据中暂无 def 类装备，跳过');
  }

  console.log('  --- 存档索引（首页秒读） ---');
  G.saveGame();
  var meta19 = G.readMeta();
  check('存档索引可读', !!meta19 && !!meta19.name, meta19 && meta19.name);
  check('索引含离线计算关键字段（gameElapsed）',
    meta19 && typeof meta19.gameElapsed === 'number' && meta19.gameElapsed > 0,
    Math.round(meta19.gameElapsed) + ' 游戏秒');
  /* v90.93：年号纪元退役 —— 索引不再记 era / yearName，改为普通年序 year。 */
  check('索引含年序/季节/天时（v90.93：年号两字段已退役）',
    typeof meta19.era === 'undefined' && typeof meta19.yearName === 'undefined'
    && !!meta19.year && !!meta19.season && !!meta19.weather,
    '第 ' + meta19.year + ' 年 ' + meta19.season + ' ' + meta19.weather);
  check('索引含城市/兵力概要', meta19.cities > 0 && typeof meta19.army === 'number',
    '城' + meta19.cities + ' 兵' + meta19.army);
  var rulerBefore = JSON.stringify(S19.ruler);
  var parsed19 = JSON.parse(localStorage.getItem('sanguo_save_v3'));
  var m19 = G.metaOf(parsed19);
  check('metaOf 为纯函数（不污染运行中 state）', JSON.stringify(S19.ruler) === rulerBefore);
  check('metaOf 可从主档独立推算', !!m19 && m19.year === meta19.year);
  check('索引体积远小于主档', JSON.stringify(meta19).length < 2000,
    JSON.stringify(meta19).length + ' B vs 主档 ' +
    Math.round(localStorage.getItem('sanguo_save_v3').length / 1024) + ' KB');
  check('存档时间可格式化', /^\d{4}-\d{2}-\d{2}/.test(G.metaTimeText(meta19.savedAt)),
    G.metaTimeText(meta19.savedAt));

  console.log('  --- 离线补算（与记账联动） ---');
  var e19 = S19.world.elapsed;
  var gold19 = S19.res.gold;
  G.offlineCatchup(600);          // 模拟离线 10 分钟（精确段）
  check('离线补算推进历法时间', S19.world.elapsed > e19,
    '+' + Math.round(S19.world.elapsed - e19) + ' 游戏秒');
  check('离线期间资源有结算', S19.res.gold !== gold19 || S19.res.grain > 0);
  /* v89.218：原「离线归来记史书」三条断言随史册退役 —— 归来可见性由「归来报告」承接。 */
  check('v89.218：离线归来报告已归集（原史书条目位置）',
    !!(G._offlineReport && G._offlineReport.secReal >= 600), JSON.stringify(G._offlineReport || {}).slice(0, 60));
  check('v89.218：chronicle 字段不再写入（老档字段不复活）', S19.chronicle === undefined);
  var e19b = S19.world.elapsed;
  G.simulateBulk(7200);            // 聚合段：2 小时
  check('聚合补算推进历法', S19.world.elapsed > e19b,
    '+' + Math.round(S19.world.elapsed - e19b) + ' 游戏秒');
  check('聚合补算不逐秒循环（性能安全）', true, 'bulk=' + 7200 + 's 一次算完');
  var q19 = S19.queues.build.length;
  S19.queues.build.push({ cityId: city19.id, extIdx: -1, buildId: 'farm', type: 'ext_build', elapsed: 0, totalTime: 10 });
  G.simulateBulk(100);
  check('聚合补算能结算队列完成', S19.queues.build.length <= q19 + 1,
    '队列 ' + S19.queues.build.length + ' 个');

  console.log('\n===== 20. 建筑功能（征召大厅/英雄枢纽/战储仓/交易站/载具研究所）=====');
  var S20 = G.state;
  var fs20 = require('fs'), path20 = require('path');
  var c20 = S20.cities[0];

  function putBldg(id, lv) {
    var i = c20.cells.findIndex(function (c) { return !c.build && !c.official; });
    if (i < 0) return false;
    c20.cells[i].build = { id: id, lvl: lv };
    return true;
  }

  console.log('  --- 征召大厅招募 ---');
  S20.generals.length = 1;                    // 只留初始英雄
  check('无征召大厅时不可招募', (function () {
    c20.cells.forEach(function (c) { if (c.build && c.build.id === 'kezhan') c.build = null; });
    return !G.canRecruitGeneral().ok;
  })(), G.canRecruitGeneral().msg);

  check('建造征召大厅与英雄枢纽', putBldg('kezhan', 3) && putBldg('zhaoxianguan', 5));
  check('征召大厅等级可读', G.innLevel() === 3, 'Lv' + G.innLevel());
  var cands20 = G.innRefresh();
  check('候选数 = 征召大厅等级（每级1位）', cands20.length === 3, cands20.length + ' 位');
  check('候选含四维属性', cands20[0].tong > 0 && cands20[0].nz > 0 && cands20[0].yw > 0 && cands20[0].zm > 0,
    '统' + cands20[0].tong + ' 内' + cands20[0].nz + ' 勇' + cands20[0].yw + ' 智' + cands20[0].zm);
  check('候选带资质字段', !!DATA.GEN_RANK_BY_ID[cands20[0].rank], cands20[0].rank);
  /* v91.56：候选四维 = roll(base) + 等级成长（随候选等级）——带宽放宽以容成长量（原 1.12 偏紧，偶发假红）。 */
  check('候选四维落在该资质区间内（按风格倍率验算）', (function () {
    var bad = [];
    cands20.forEach(function (c) {
      var rk = DATA.GEN_RANK_BY_ID[c.rank];
      var lo = Math.floor(rk.base[0] * 0.85), hi = Math.ceil(rk.base[1] * 1.5);
      if (c.tong < lo || c.tong > hi) bad.push(c.name + ' 统' + c.tong);
    });
    return bad.length === 0;
  })(), cands20.map(function (c) { return c.name + '(统' + c.tong + ' ' + c.rank + ')'; }).join(' '));
  check('高资质四维区间上限更高（凡人<突变体<进化体<觉醒体<天启体）', (function () {
    var order = ['fan', 'liang', 'ying', 'ming', 'tian'];
    for (var i = 1; i < order.length; i++) {
      if (DATA.GEN_RANK_BY_ID[order[i]].base[1] <= DATA.GEN_RANK_BY_ID[order[i - 1]].base[1]) return false;
    }
    return true;
  })());
  check('候选含英雄与美人两类', cands20.every(function (c) { return typeof c.beauty === 'boolean'; }));
  check('候选有招募成本', cands20[0].cost > 0, U.fmt(cands20[0].cost) + ' 金');
  check('候选定时刷新机制存在', G.innRefreshLeft() >= 0, Math.ceil(G.innRefreshLeft() / 1000) + ' 秒后更换');

  var gold20 = S20.res.gold;
  var rc20 = G.innRecruit(cands20[0].id);
  check('招募成功', rc20.ok === true, rc20.msg);
  check('招募消耗旧币', S20.res.gold < gold20, U.fmt(gold20) + ' → ' + U.fmt(S20.res.gold));
  check('英雄入帐', S20.generals.length === 2, S20.generals.length + ' 人');
  check('新将有属性与忠诚', S20.generals[1].tong > 0 && S20.generals[1].loyalty > 0,
    S20.generals[1].name + ' 统' + S20.generals[1].tong + ' 忠' + S20.generals[1].loyalty);
  check('候选人从列表移除', G.innRefresh().length === 2, G.innRefresh().length + ' 位');

  var g20b = S20.res.gold;
  g20b = S20.res.gold;
  var rr20 = G.innReroll();
  check('花金可另请一批', rr20.ok === true, rr20.msg);
  check('候选数量恢复', G.innRefresh(true).length === 3);

  /* v89.62（老板）：「增加自动招募按钮，可设置当征召大厅刷新出什么品质的时候自动招募，
     直至达到英雄枢纽空位上限」—— 这条**真跑一遍**（源断言抓不到运行时错误）：
     手工注入 3 位候选（凡人 / 进化体 / 觉醒体），门槛设"进化体"，
     则应招走进化体与觉醒体（2 人）、凡人留下（未达门槛），且不超英雄枢纽容量。 */
  check('v89.64：征召大厅在**后台**也会换批（tickOnce 挂 innRefresh → 自动招募才可能被触发）', (function () {
    var st = stripComment(require('fs').readFileSync(require('path').join(__dirname, 'js', 'state.js'), 'utf8'));
    var tick = codeOf(st, 'GAME.tickOnce = function');
    /* 老板「征召大厅出现相应要求的英雄时触发招募」——若只在打开征召大厅时才换批，
       后台永远不会"出现相应要求的英雄"，自动招募也就永远不触发。 */
    return /GAME\.innRefresh\(\)/.test(tick) && /GAME\.innAutoRun/.test(tick);
  })());
  check('v89.62：自动招募（门槛生效 · 达标者招走 · 未达标留下 · 不超容量）', (function () {
    var s = GAME.state, city = GAME.currentCity();
    var keepGens = s.generals.slice();
    /* v89.108：候选池按城独立 —— 注入/还原都走唯一出口 innPoolOf（不再直接改 s.inn）。 */
    var pool = GAME.innPoolOf(city);
    var keepCand = pool.candidates.slice();
    var keepAt = pool.at;
    var keepGold = s.res.gold || 0;
    var cfg = GAME.innAutoCfg(), keepOn = cfg.on, keepMin = cfg.min;
    var mk = function (rank, i) {
      return { id: 'T' + i, name: '测试候选' + i, rank: rank, level: 1, style: 'balance',
        tong: 50, nz: 50, yw: 50, zm: 50, cost: 1000, loyalty: 70 };
    };
    /* at 设为"刚刚" → innRecruit 内部那次 innRefresh 走缓存分支，注入的候选不会被换掉 */
    pool.candidates = [mk('fan', 1), mk('ying', 2), mk('ming', 3)];
    pool.at = U.now();
    s.res.gold = Math.max(keepGold, 100000);
    cfg.on = true; cfg.min = 'ying';
    var r = GAME.innAutoRun();
    var left = pool.candidates.map(function (c) { return c.rank; });
    var inCity = GAME.generalsIn(city).length;
    var cap = GAME.genSlotsOf(city);
    /* 还原（**原地改**，别换数组对象 —— 别处可能持有旧引用） */
    s.generals.length = 0;
    keepGens.forEach(function (g) { s.generals.push(g); });
    s.res.gold = keepGold;
    pool.candidates = keepCand; pool.at = keepAt;
    cfg.on = keepOn; cfg.min = keepMin;
    return r.n === 2 && left.length === 1 && left[0] === 'fan' && inCity <= cap;
  })(), '招走 ' + 2 + ' 人 · 门槛外留下凡人 1 人');

  console.log('  --- 英雄枢纽容量 ---');
  /* v64（老板）：「根据**该城的英雄枢纽等级**有相应空位」——
     `generalCap()`（当前城一格卡全境）已删，改为按城的 `genSlotsOf(city)`。 */
  check('英雄席位 = 该城英雄枢纽等级', G.genSlotsOf(c20) === 5 && G.genSlotsTotal() >= 5,
    '本城 ' + G.genSlotsOf(c20) + ' 席 · 全境合计 ' + G.genSlotsTotal() + ' 席');
  var keep20 = S20.generals.slice();
  while (S20.generals.length < 5) S20.generals.push(G.makeGeneral('测试将' + S20.generals.length, 1, 'idle', c20.id, false));
  var full20 = G.canRecruitGeneral();
  check('满员时拒绝招募', full20.ok === false, full20.msg);
  check('满员提示指向英雄枢纽', /英雄枢纽/.test(full20.msg));
  S20.generals.length = 0; keep20.forEach(function (g) { S20.generals.push(g); });

  console.log('  --- 战储仓储量 ---');
  check('无战储仓时为基础储量', (function () {
    c20.cells.forEach(function (c) { if (c.build && c.build.id === 'cangku') c.build = null; });
    /* v79：储量吃"名城/威望/主城/神器"加成 —— 期望值同步走唯一汇总口 */
    /* v89.141：容量多一项"城外露天"（纯加法）——期望值同步加 extStoreCapOf */
    return G.storeCap() === Math.round(2000000 * (1 + G.cityBonusNum(G.currentCity(), 'storePct')))
      + G.extStoreCapOf(G.currentCity());
  })(), U.fmt(G.storeCap()));
  check('建造战储仓', putBldg('cangku', 3));
  check('战储仓提升储量上限（每级+200万）',
    G.storeCap() === Math.round(6000000 * (1 + G.cityBonusNum(G.currentCity(), 'storePct')))
      + G.extStoreCapOf(G.currentCity()), U.fmt(G.storeCap()));
  /* v89.212（老板 1）：两项均改**粮自己的**上限口径（城外堆场按资源分账）——
     全城"合计上限"不再是任何资源的封顶尺度（规则变更所致）。 */
  var overCap = G.storeCapOf(G.currentCity(), 'grain') + 999999;
  S20.res.grain = overCap;
  G.tickOnce();
  /* v89.158（老板 1）：口径拆两条 —— ① 已有存量**不被削**（改前超上限的 999,999
     会在下一 tick 被静默削回 cap）；② 自然增长仍受上限约束（不越过、到顶停涨）。 */
  check('超上限存量不被削（v89.158：只封增长、不砍已有）', S20.res.grain === overCap,
    U.fmt(S20.res.grain) + ' / ' + U.fmt(G.storeCapOf(G.currentCity(), 'grain')));
  S20.res.grain = Math.max(0, G.storeCapOf(G.currentCity(), 'grain') - 100);
  G.tickOnce();
  check('自然增长受储量上限约束（不越过上限）',
    S20.res.grain <= G.storeCapOf(G.currentCity(), 'grain')
    && S20.res.grain >= G.storeCapOf(G.currentCity(), 'grain') - 100,
    U.fmt(S20.res.grain) + ' / ' + U.fmt(G.storeCapOf(G.currentCity(), 'grain')));

  console.log('  --- 交易站交易 ---');
  /* v89.62（老板「交易站去除商队计数和限制，去除相应标注」）：
     旧断言是"无交易站时不可交易" —— **它其实一直是个假绿**（失败原因是库存不足，不是无交易站）。
     新政策：不设门槛，无交易站也能交易，代价是折损取 0.6 底；交易站等级只影响折损。 */
  check('无交易站也能交易（折损取 0.6 底 · 等级只影响折损）', (function () {
    var s = GAME.state;
    var keepG = s.res.grain || 0;
    s.res.grain = Math.max(keepG, 200000);
    c20.cells.forEach(function (c) { if (c.build && c.build.id === 'shichang') c.build = null; });
    var lvNo = G.marketLevel();
    var rate0 = G.marketRate();
    var okTrade = G.marketTrade('grain', 'wood', 100).ok === true;
    s.res.grain = keepG;
    return lvNo === 0 && rate0 === 0.6 && okTrade;
  })());
  check('建造交易站', putBldg('shichang', 5));
  check('交易站提供汇率', G.marketRate() > 0.6 && G.marketRate() <= 0.95, '1 : ' + G.marketRate().toFixed(2));
  S20.res.grain = 100000; S20.res.wood = 0;
  var tr20 = G.marketTrade('grain', 'wood', 10000);
  check('资源兑换成功', tr20.ok === true, tr20.msg);
  check('换得量含折损', S20.res.wood > 0 && S20.res.wood < 10000, '10000 粮 → ' + S20.res.wood + ' 木');
  check('支出资源被扣除', S20.res.grain === 90000, U.fmt(S20.res.grain));
  check('非法交易被拒', G.marketTrade('grain', 'grain', 100).ok === false);

  /* --------- v89.48（老板）：「交易站可以售卖资源，换取旧币，比例 1,2,3,4，净水最便宜」 --------- */
  console.log('  --- v89.48 交易站售卖换金 ---');
  check('v89.48：比例表 = 粮1 : 木2 : 石3 : 铁4（净水最便宜 · 分母 > 0）', (function () {
    var c = DATA.MARKET_SELL;
    return !!c && c.ratio && c.ratio.grain === 1 && c.ratio.wood === 2
      && c.ratio.stone === 3 && c.ratio.iron === 4
      && c.per > 0 && (c.res || []).join(',') === 'grain,wood,stone,iron';
  })());
  check('v89.48：单价严格成 1:2:3:4（四类同乘交易站系数 → 比例恒定）', (function () {
    var g0 = G.marketSellPer('grain');
    if (!(g0 > 0)) return false;
    return Math.abs(G.marketSellPer('wood') / g0 - 2) < 1e-9
      && Math.abs(G.marketSellPer('stone') / g0 - 3) < 1e-9
      && Math.abs(G.marketSellPer('iron') / g0 - 4) < 1e-9;
  })());
  check('v89.48：整单售价 = floor(数量 × 单价)（与单价同源 · 单调）', (function () {
    var ok1 = G.marketSellGold('grain', 1000) === Math.floor(1000 * G.marketSellPer('grain'));
    return ok1 && G.marketSellGold('iron', 1000) > G.marketSellGold('stone', 1000)
      && G.marketSellGold('stone', 1000) > G.marketSellGold('wood', 1000)
      && G.marketSellGold('wood', 1000) > G.marketSellGold('grain', 1000);
  })());
  check('v89.48：门槛 = ceil(1 / 单价)（不足则明确拒绝，不产生 0 旧币交易）', (function () {
    var m = G.marketSellMin('grain');
    return m >= 1 && G.marketSellGold('grain', m) >= 1
      && G.marketSellGold('grain', m - 1) < 1
      && G.marketSell('grain', Math.max(0, m - 1)).ok === false;
  })());
  check('v89.48：售卖结算（扣资源 · 加金 · 数额恰为 marketSellGold）', (function () {
    S20.res.grain = 50000; S20.res.gold = 1000;
    var want = G.marketSellGold('grain', 10000);
    var r = G.marketSell('grain', 10000);
    return r.ok && r.gold === want && want > 0
      && S20.res.grain === 40000 && S20.res.gold === 1000 + want;
  })(), '1 万粮 → ' + G.marketSellGold('grain', 10000) + ' 金');
  check('v89.48：四类都卖得动 · 旧币本身不可卖', (function () {
    var allOk = ['grain', 'wood', 'stone', 'iron'].every(function (k) {
      S20.res[k] = Math.max(S20.res[k] || 0, 50000);
      var gold0 = S20.res.gold;
      var r = G.marketSell(k, 50000);
      return r.ok && S20.res.gold > gold0;
    });
    return allOk && G.marketSell('gold', 100).ok === false;
  })());
  check('v89.62：交易站护栏（库存不足 / 数量无效 全拒；**无交易站不再拒**，只是折损最大）', (function () {
    var s = GAME.state;
    var noStock = G.marketSell('grain', 99999999).ok === false;
    var zero = G.marketSell('grain', 0).ok === false;
    /* 库存先垫足 —— 否则"以为在测无交易站，其实测的是库存不足"（旧断言就是这么假绿的） */
    var keepG = s.res.grain || 0, keepGold = s.res.gold || 0;
    s.res.grain = Math.max(keepG, 200000);
    var saved = [];
    c20.cells.forEach(function (c) { if (c.build && c.build.id === 'shichang') { saved.push(c.build); c.build = null; } });
    var lvNo = G.marketLevel();
    var rate0 = G.marketRate();                 /* 无交易站 → 折损落到 0.6 底 */
    var noMkt = G.marketSell('grain', 10000);   /* 老板「去除限制」：这一笔应当**成功** */
    saved.forEach(function (b, i) { c20.cells.forEach(function (c) { if (!c.build && i-- === 0) c.build = b; }); });
    var lvBack = G.marketLevel();
    s.res.grain = keepG; s.res.gold = keepGold;  /* 还原，避免影响后续断言 */
    return noStock && zero && lvNo === 0 && rate0 === 0.6 && noMkt.ok === true && lvBack > 0;
  })());
  check('v89.60：交易站为**单块**（一张表 · 每行买卖 · 共用数量框 · 三块旧结构退场）', (function () {
    var uSrc = stripComment(fsMod.readFileSync(pathMod.join(__dirname, 'js', 'ui.js'), 'utf8'));
    var mSrc = stripComment(fsMod.readFileSync(pathMod.join(__dirname, 'js', 'main.js'), 'utf8'));
    var fn = codeOf(uSrc, 'ui.openMarket = function');
    return /class="ms-table"/.test(fn)
      && /'grain', 'wood', 'stone', 'iron'/.test(fn)                 /* 四资源同表 */
      && /data-action="market-sell" data-res=/.test(fn)               /* 每行：卖出 */
      && /data-action="market-buy" data-res=/.test(fn)                /* 每行：买入 */
      && /id="mk-amount"/.test(fn)                                    /* 数量唯一出口 */
      /* 单块的判据 = 旧三块的控件全部退场（互换的两端 + 售卖/买入各自的资源隐藏域） */
      && !/mk-from|mk-to|mk-sell-res|mk-buy-res/.test(fn)
      && !/ui\.marketSellHTML|ui\.marketBuyHTML/.test(uSrc)
      /* 价目只读出口：界面不自己算单价 */
      && /GAME\.marketSellGold\(k, 1000\)/.test(fn) && /GAME\.marketBuyGoldFor\(k, 1000\)/.test(fn)
      /* main.js：两个方向各自带 data-res 分发 */
      && /GAME\.doMarketSell = function/.test(mSrc) && /GAME\.doMarketBuy = function/.test(mSrc)
      && /GAME\.doMarketSell\(el\.dataset\.res\)/.test(mSrc)
      && /GAME\.doMarketBuy\(el\.dataset\.res\)/.test(mSrc)
      && DATA.GOLD_GATE.market != null;
  })());
  check('v89.60：反向口径 marketBuyGoldFor（买 N 单位折出的金 → 成交得货 ≥ N）', (function () {
    var s = GAME.state, res = 'iron', units = 400;
    var keepGold = s.res.gold || 0, keepRes = s.res[res] || 0, keepTr = (s.stats && s.stats.trades) || 0;
    s.res.gold = 1000000;
    var need = G.marketBuyGoldFor(res, units);
    var r = G.marketBuy(res, need);
    var got = (s.res[res] || 0) - keepRes;
    s.res.gold = keepGold; s.res[res] = keepRes;
    if (s.stats) s.stats.trades = keepTr;
    /* 口径要点：买 N 单位**不许少给**（got ≥ N），最多多给 1~2 单位（向上取整的零头） */
    return need > 0 && r.ok === true && got >= units && got <= units + 2;
  })());
  check('v89.62：交易站去「商队」（口径正名 marketLevel · 无门槛 · 界面不标商队 · 量级按钮）', (function () {
    var rd = function (f) { return stripComment(require('fs').readFileSync(require('path').join(__dirname, 'js', f), 'utf8')); };
    var u = rd('ui.js'), d = rd('domain.js'), da = rd('data.js'), m = rd('main.js');
    return !/caravanCount/.test(d + u + m)                 /* "商队数"这个口径整体退场 */
      && /GAME\.marketLevel = function/.test(d)             /* 正名为交易站等级 */
      && !/需先建造交易站/.test(d)                             /* 交易门槛撤销（无交易站也能买卖） */
      && !/商队/.test(u) && !/商队/.test(da)                 /* 界面与数据层的"商队"标注清零 */
      && /data-action="mk-scale"/.test(u)                    /* 量级缩放按钮 */
      && /'10 万'/.test(u) && /'百万'/.test(u) && /'千万'/.test(u) && /'亿'/.test(u)
      && /case 'mk-scale'/.test(m);
  })());

  console.log('  --- 载具研究所作为机车前置 ---');
  check('伏击车需载具研究所1级', DATA.TROOPS.fujiche.unlock.majiu === 1);
  check('主战机甲需载具研究所3级', DATA.TROOPS.zhuzhan.unlock.majiu === 3);
  check('狂猎需载具研究所4级', DATA.TROOPS.kuanglie.unlock.majiu === 4);
  var chkM20 = G.canTrain('fujiche');
  check('未建载具研究所时伏击车不可训练', chkM20.ok === false && /载具研究所/.test(chkM20.msg), chkM20.msg);

  console.log('  --- 功能归属与自动存档 ---');
  var uiSrc20 = fs20.readFileSync(path20.join(__dirname, 'js', 'ui.js'), 'utf8');
  var mainSrc20 = fs20.readFileSync(path20.join(__dirname, 'js', 'main.js'), 'utf8');
  check('建筑功能入口表存在', /BLDG_FUNC/.test(uiSrc20));
  /* v89.80（老板）：「载具研究所去除"座驾装备"的建筑菜单及相应内容」——
     majiu 从"必须有菜单"的名单里移出，并**反向钉住**（无菜单项 → 缺 BLDG_FUNC 项时
     "功能"整块不渲染，这正是老板要的：点载具研究所格只剩属性行）。 */
  ['junying', 'xiaochang', 'shuyuan', 'kezhan', 'zhaoxianguan', 'shichang', 'cangku'].forEach(function (bid) {
    check('功能归属：' + bid, new RegExp(bid + ':').test(uiSrc20.match(/var BLDG_FUNC = \{[\s\S]*?\};/)[0]));
  });
  check('功能归属：majiu **无**菜单项（v89.80 老板撤除「座驾装备」入口）',
    !/majiu\s*:\s*\{/.test(uiSrc20.match(/var BLDG_FUNC = \{[\s\S]*?\};/)[0]));
  check('自动存档间隔为 5 分钟', /AUTO_SAVE_MS = 5 \* 60 \* 1000/.test(mainSrc20));
  check('自动存档为覆盖式写入（同键替换）', /saveGame\(\)/.test(mainSrc20) && /SAVE_KEY/.test(fs20.readFileSync(path20.join(__dirname, 'js', 'state.js'), 'utf8')));
  check('募兵归属军队面板 / 出征归属地图', /junying: \{ label: \"[^\"]*募兵\"[^}]*view: \"troops\"/.test(uiSrc20.replace(/\s+/g, ' ')) ||
    /junying/.test(uiSrc20) && /xiaochang/.test(uiSrc20));

  console.log('\n===== 21. 自动升级 =====');
  var S21 = G.state;
  var city21 = S21.cities[0];

  function minUpgradableLv() {
    var m = 99;
    city21.cells.forEach(function (c) {
      if (!c.build || c.pending || c.official) return;
      var b = DATA.BUILDINGS[c.build.id];
      if (b && c.build.lvl < b.maxLevel) m = Math.min(m, c.build.lvl);
    });
    (extOf(S21) || []).forEach(function (e) {
      if (!e || !e.type || e.pending) return;
      var eb = DATA.EXT_BUILDINGS[e.type];
      if (eb && e.lv < 10) m = Math.min(m, e.lv);
    });
    /* v89.126：围墙占格后**由上面的 cells 扫描天然包含**（`chengqiang` 是普通建筑）——
       原"单独把 city.wallLv 算进最低等级"整段退役。 */
    return m;
  }
  function giveRes21() {
    /* v89.235（老板）规则变更配套：城外资源建筑等级 ≤ 政务厅等级 后，
       "确定可升项"可能落在别的城（该城政务厅未到顶）—— 自动升级 v89.167 起本就
       遍历全境，"资源恢复"按其真实作用域取**全境**（原只给当前城）。 */
    (S21.cities || []).forEach(function (ct) {
      ['grain', 'wood', 'stone', 'iron'].forEach(function (k) { ct.res[k] = 5000000; });
      ct.res.gold = 5000000;
    });
  }

  check('默认关闭（避免不知情耗尽资源）', DATA.DEFAULT_SETTINGS.autoUpgrade === false);
  S21.settings.autoUpgrade = false;
  S21.queues.build.length = 0;
  var au0 = G.autoUpgrade();
  check('关闭时不做任何事', au0 === null && S21.queues.build.length === 0);

  S21.settings.autoUpgrade = true;
  S21.queues.build.length = 0;
  giveRes21();
  var wantLv = minUpgradableLv();
  var au1 = G.autoUpgrade();
  check('开启后自动排队升级', !!(au1 && au1.ok),
    au1 && au1.target ? (au1.target.name + ' → Lv' + (au1.target.lv + 1)) : '无动作');
  /* v89.167（老板 · 每城独立建造位）：一次调用**把各城空位排满**（不再一条一条来）——
     原断言 `=== 1` 是"一次一条"的旧口径。 */
  check('升级已进入建造队列（v89.167：一次调用即排入）',
    S21.queues.build.length >= 1, S21.queues.build.length + ' 个队列');
  check('优先升级等级最低者（v89.126：围墙占格后，未建不参与候选 —— 与其它建筑一致）', (function () {
    if (!(au1 && au1.target) || au1.target.lv !== wantLv) return false;
    /* 旧口径：围墙"永远存在（Lv0）"必然最低 → 自动升级先修墙；
       新口径：围墙占格、未建则不在候选里（和科研中心/练兵场等一样，需玩家先建）——
       自动升级只做"升级"，不代建未建建筑。 */
    var anyWallCell = S21.cities.some(function (ct) {
      return (ct.cells || []).some(function (x) { return x.build && x.build.id === 'chengqiang'; });
    });
    return anyWallCell ? true : (au1.target.kind !== 'wall');
  })(), '目标 ' + (au1 && au1.target ? (au1.target.kind + ' Lv' + au1.target.lv) : '?')
    + '（当前最低 Lv' + wantLv + '）');
  check('记录了自动升级状态', !!S21.autoState && !S21.autoState.paused, S21.autoState && S21.autoState.msg);

  /* v89.167（老板）：核心口径 = **各城不超各自建造位**（改前 = 全境合计受"当前城位"压 ——
     全境一共只排 3 条）。一次调用后再来一次，逐城核对不越界。 */
  var au2 = G.autoUpgrade();
  var usedByCity21 = {};
  S21.queues.build.forEach(function (q) { usedByCity21[q.cityId] = (usedByCity21[q.cityId] || 0) + 1; });
  check('★ 各城不超各自建造位（v89.167 每城独立 · 不再全境合抢一个额度）',
    S21.cities.every(function (c) { return (usedByCity21[c.id] || 0) <= G.buildSlots(c); }),
    JSON.stringify(usedByCity21));
  var slots21 = G.buildSlots();
  check('本城队列不超上限', (usedByCity21[city21.id] || 0) <= slots21,
    (usedByCity21[city21.id] || 0) + ' / 上限 ' + slots21);
  /* v89.93（整改 E8）：基础槽位 2 → 3 后，这里**先把队列填满**再验"满则不再排队" */
  var fillGuard21 = 0;
  while (S21.queues.build.length < slots21 && fillGuard21++ < 8) {
    if (!G.autoUpgrade()) break;
  }
  var full21 = S21.queues.build.length;
  var au3 = G.autoUpgrade();
  /* v89.167：全境视角下"某城满、他城缺资源"时返回的是暂停态（非 null）——
     判据改为"**不再排入**"（非 ok），比"=== null"更贴语义。 */
  check('队列满时不再排队（不再排入 · 队列数不增）',
    S21.queues.build.length === full21 && !(au3 && au3.ok),
    S21.autoState && S21.autoState.msg);

  /* 资源不足 → 暂停（v89.235：与 giveRes21 同口径 —— 全境清） */
  S21.queues.build.length = 0;
  (S21.cities || []).forEach(function (ct) {
    ['grain', 'wood', 'stone', 'iron'].forEach(function (k) { ct.res[k] = 0; });
  });
