    check('首府战利品可掉成品装备', gotPiece > 0, gotPiece + ' 次/400');
    check('旧都图纸掉落率高于重镇', DATA.LOOT_EQUIP.capital.blueprint > DATA.LOOT_EQUIP.jun.blueprint);

