  var weF = gS.world.weather; gS.world.weather = 'clear';
  var bwF = gS.settings.battleWatch; gS.settings.battleWatch = false;
  var rep0F = gS.rep || 0;
  /* v89.94（B2 · E1）：据点「占领」= **围攻** —— 第一波只破防，不下城（多波次磨） */
