  var left2 = G.autoMarchTodayLeft(cfg);
  var r = G.autoMarchOnce(cfg);
  cfg.dailyMax = bk.dailyMax; cfg.todayCount = bk.todayCount; cfg.todayKey = bk.key;
  return left0 === 2 && left2 === 0 && r.ok === false && /上限/.test(r.msg);
