      var hasAdd = /var ext = GAME\.extStoreCapOf\(city\);/.test(do122)
        && /total: base \+ ext/.test(do122)
        /* v89.212（老板 1）：按资源分账 —— 签名带 key（city, key）+ byRes 底账在册 */
        && /GAME\.extStoreCapOf = function \(city, key\)/.test(do122)
