        if (!sid) return 'SKIP-无在售';
        var it = GAME.systems.itemInfo(sid);
        st.res.gold = (it.price * 100) * 5;
        st.shopDay = { key: '', bought: {} };
        var before = GAME.items.count(sid);
        var r = GAME.doShopping(sid, 2);
